<section class="sl-card col g8"><h2 class="sl-ct">Price list calculation</h2><div class="sl-kv"><div><span>Price per <?= h($d['unit']) ?></span><span class="mono"><?= h(sl_money($d['rate'])) ?></span></div><div><span>Subtotal</span><span class="mono" id="nc-sub"><?= h(sl_money(0)) ?></span></div><div><span>Discount</span><span class="row g6"><input class="sl-in mono" name="discount_value" id="nc-disc" type="number" min="0" max="100" step="0.5" style="width:66px;height:30px" value="0" aria-label="Discount percent">%</span></div><div><span>Value assured</span><span class="row g6"><input class="sl-in mono" name="insured_value" id="nc-insv" type="number" min="0" step="0.01" style="width:96px;height:30px" value="0" aria-label="Value assured"></span></div><div><span>Shipping insurance <?= h($d['insurance']) ?>%</span><span class="mono" id="nc-ins"><?= h(sl_money(0)) ?></span></div><div><span>Customs duties %</span><span class="row g6"><input class="sl-in mono" name="tariffs_value" id="nc-duty" type="number" min="0" step="0.5" style="width:66px;height:30px" value="0" aria-label="Customs percent"></span></div><div><span>Tax <?= h($d['tax']) ?>%</span><span class="mono" id="nc-tax"><?= h(sl_money(0)) ?></span></div><div><span>Reissue</span><span class="row g6"><input class="sl-in mono" name="reexpedicion_value" id="nc-reex" type="number" min="0" step="0.01" style="width:96px;height:30px" value="0" aria-label="Reissue"></span></div><div><span class="fw5">TOTAL</span><span class="mono fw5" id="nc-tot"><?= h(sl_money(0)) ?></span></div></div>
<button class="sl-btn block" type="submit" style="height:46px"><i class="ic ic-sm i-check" aria-hidden="true"></i>Save consolidated shipments</button><span class="mut sm">Totals are recalculated on the server from the packages you pick.</span></section></aside></div>
</form>
<script>
(function () {
  var C = { rate: <?= json_encode($d['rate']) ?>, tax: <?= json_encode($d['tax']) ?>, ins: <?= json_encode($d['insurance']) ?>, cap: <?= json_encode($d['cap']) ?>, unit: <?= json_encode($d['unit']) ?>, sym: <?= json_encode($core->for_symbol ?? '$') ?> };
  var f = document.getElementById('nc-form'), sel = {};
  function m(n) { return C.sym + n.toFixed(2).replace(/\B(?=(\d{3})+(?!\d))/g, ','); }
  function v(id) { return +document.getElementById(id).value || 0; }
  function calc() {
    var ids = Object.keys(sel), w = 0, cs = {}, amt = 0;
    ids.forEach(function (k) { w += sel[k].w; cs[sel[k].c] = 1; amt += sel[k].a; });
    var sub = w * C.rate, disc = sub * v('nc-disc') / 100, ins = v('nc-insv') * C.ins / 100, duty = w * v('nc-duty') / 100, tax = (sub - disc) * C.tax / 100, tot = sub - disc + ins + duty + tax + v('nc-reex');
    var pct = Math.min(100, Math.round(w / (C.cap || 1) * 100));
    document.getElementById('nc-ids').value = ids.join(',');
    document.getElementById('nc-note').textContent = ids.length ? ids.length + ' selected' : 'Nothing selected';
    document.getElementById('nc-n').textContent = ids.length; document.getElementById('nc-c').textContent = Object.keys(cs).length; document.getElementById('nc-w').textContent = w.toFixed(1) + ' ' + C.unit; document.getElementById('nc-amt').textContent = m(amt);
    document.getElementById('nc-bar').style.width = pct + '%'; document.getElementById('nc-bar').className = pct >= 95 ? 'r' : (pct >= 70 ? 'y' : ''); document.getElementById('nc-pct').textContent = pct + '%'; document.getElementById('nc-cap').textContent = w.toFixed(0) + ' of ' + C.cap.toFixed(0) + ' ' + C.unit;
    document.getElementById('nc-sub').textContent = m(sub); document.getElementById('nc-ins').textContent = m(ins); document.getElementById('nc-tax').textContent = m(tax); document.getElementById('nc-tot').textContent = m(tot);
  }
  function toggle(b, on) { var id = b.getAttribute('data-oid'); if (on) sel[id] = { w: +b.getAttribute('data-w'), c: b.getAttribute('data-c'), a: +b.getAttribute('data-amt') }; else delete sel[id]; b.classList.toggle('on', on); b.querySelector('.sl-chk').classList.toggle('on', on); }
  f.addEventListener('click', function (e) { var b = e.target.closest('.cd-av'); if (!b) return; toggle(b, !sel[b.getAttribute('data-oid')]); calc(); });
  document.getElementById('nc-all').addEventListener('click', function () { var all = f.querySelectorAll('.cd-av'), on = Object.keys(sel).length < all.length; all.forEach(function (b) { toggle(b, on); }); this.textContent = on ? 'Clear selection' : 'Select all'; calc(); });
  f.addEventListener('input', function (e) { if (e.target.name === 'code_prefix' || e.target.name === 'order_no') { var t = f.code_prefix.value + f.order_no.value; document.getElementById('nc-ident').value = t; document.getElementById('nc-ident2').textContent = t; } calc(); });
  document.getElementById('nc-q').addEventListener('keydown', function (e) { if (e.key === 'Enter') { e.preventDefault(); var u = new URL(location.href); u.searchParams.set('q', this.value); location.href = u; } });
  calc();
})();
</script>
